local c="" local a="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/" local d={} for i=1,#a do d[a:sub(i,i)]=i-1 end local o={} for i=1,#c,4 do local x=d[c:sub(i,i)] or 0 local y=d[c:sub(i+1,i+1)] or 0 local z=d[c:sub(i+2,i+2)] or 0 local w=d[c:sub(i+3,i+3)] or 0 o[#o+1]=string.char(x*4+math.floor(y/16)) if c:sub(i+2,i+2)~="=" then o[#o+1]=string.char((y%16)*16+math.floor(z/4)) end if c:sub(i+3,i+3)~="=" then o[#o+1]=string.char((z%4)*64+w) end end local f,e=(loadstring or load)(table.concat(o)) if not f then warn("[Luavify] Bootstrap error: "..tostring(e)) return end return f()